// ---------------------------------------------------------------------------
// AUTO-GENERATED by Claude Code
// Purpose: the multi-select of tool forms (render._multi_select), for any tool parameter typed
//          list[<a fixed set of values>] (tool_forms.list_choices): a box showing what is picked
//          that opens a list to tick options in, with a search box when the list is long.
// Markup it drives (all rendered by Reflex, found by data- attributes):
//   [data-multi]           the wrapper; gets .is-open while the list shows
//   [data-multi-toggle]    the box (a button) that opens / closes the list
//   [data-multi-summary]   inside the box: what is picked (icons + names); this script owns it
//   [data-multi-value]     the hidden input the form submits: picked values joined by ","
//   [data-multi-panel]     the list: [data-multi-search]? [data-multi-any] then .multi-option
//                          buttons with data-value, data-label, data-icon ("" = no icon)
// Keys, in the search box or on the box: arrows move, Enter / Space tick (never submit the
// form while the list is open), Escape closes. One set of listeners on document, so selects
// Reflex mounts later work without setup.
// ---------------------------------------------------------------------------
(() => {
  const SHOWN_ICONS = 4; // icons in the box before "+N"
  const SHOWN_NAMES = 2; // names in the box before "+N"

  const parts = (el) => {
    const multi = el.closest?.("[data-multi]");
    if (!multi) return null;
    return {
      multi,
      toggle: multi.querySelector("[data-multi-toggle]"),
      summary: multi.querySelector("[data-multi-summary]"),
      value: multi.querySelector("[data-multi-value]"),
      panel: multi.querySelector("[data-multi-panel]"),
      search: multi.querySelector("[data-multi-search]"),
      any: multi.querySelector("[data-multi-any]"),
    };
  };
  const options = (p) => [...p.panel.querySelectorAll(".multi-option:not([data-multi-any])")];
  const picked = (p) => p.value.value.split(",").filter(Boolean);
  const isOpen = (p) => p.multi.classList.contains("is-open");

  // the box: icons of the first picks and their names; "any" when nothing is picked
  const render = (p) => {
    const values = picked(p);
    const chosen = values.map((v) => options(p).find((o) => o.dataset.value === v)).filter(Boolean);
    options(p).forEach((o) => o.classList.toggle("is-picked", values.includes(o.dataset.value)));
    p.any.classList.toggle("is-picked", values.length === 0);
    p.summary.replaceChildren();
    if (chosen.length === 0) {
      const none = document.createElement("span");
      none.className = "dim";
      none.textContent = "any";
      p.summary.append(none);
    }
    chosen.slice(0, SHOWN_ICONS).forEach((o) => {
      if (!o.dataset.icon) return;
      const img = document.createElement("img");
      img.src = o.dataset.icon;
      img.alt = "";
      img.className = "char-icon";
      p.summary.append(img);
    });
    if (chosen.length) {
      const names = chosen.slice(0, SHOWN_NAMES).map((o) => o.dataset.label).join(", ");
      const text = document.createElement("span");
      text.className = "multi-names";
      text.textContent = chosen.length > SHOWN_NAMES ? `${names} +${chosen.length - SHOWN_NAMES}` : names;
      p.summary.append(text);
    }
    p.toggle.title = chosen.length ? chosen.map((o) => o.dataset.label).join(", ") : "any";
  };

  const setPicked = (p, values) => {
    p.value.value = values.join(",");
    render(p);
  };
  const tick = (p, option) => {
    if (option === p.any) return setPicked(p, []);
    const values = picked(p);
    const value = option.dataset.value;
    setPicked(p, values.includes(value) ? values.filter((v) => v !== value) : [...values, value]);
  };

  // the rows the keys move through: Any, then the options the search leaves
  const rows = (p) => [p.any, ...options(p).filter((o) => !o.hidden)];
  const active = (p) => p.panel.querySelector(".multi-option.is-active");
  const setActive = (p, row) => {
    p.panel.querySelectorAll(".multi-option").forEach((o) => o.classList.toggle("is-active", o === row));
    if (row) row.scrollIntoView({ block: "nearest" });
  };
  const filter = (p) => {
    const wanted = (p.search?.value || "").trim().toLowerCase();
    options(p).forEach((o) => {
      const hay = `${o.dataset.label} ${o.dataset.value}`.toLowerCase();
      o.hidden = wanted !== "" && !hay.includes(wanted);
    });
    p.any.hidden = wanted !== "";
    setActive(p, rows(p).find((row) => !row.hidden) || null);
  };

  // position: fixed under (or above) the box, so a scrolling parent (a result tab) can't clip it
  const place = (p) => {
    const box = p.toggle.getBoundingClientRect();
    const below = window.innerHeight - box.bottom;
    p.panel.style.left = `${Math.min(box.left, window.innerWidth - 250)}px`;
    if (below < 260 && box.top > below) {
      p.panel.style.top = "";
      p.panel.style.bottom = `${window.innerHeight - box.top + 2}px`;
      p.panel.style.maxHeight = `${Math.min(340, box.top - 8)}px`;
    } else {
      p.panel.style.bottom = "";
      p.panel.style.top = `${box.bottom + 2}px`;
      p.panel.style.maxHeight = `${Math.min(340, below - 8)}px`;
    }
  };

  const open = (p) => {
    document.querySelectorAll("[data-multi].is-open").forEach((m) => m !== p.multi && m.classList.remove("is-open"));
    p.multi.classList.add("is-open");
    if (p.search) p.search.value = "";
    filter(p);
    place(p);
    (p.search || p.toggle).focus();
  };
  const close = (p, refocus) => {
    p.multi.classList.remove("is-open");
    if (refocus) p.toggle.focus();
  };

  // a select Reflex just mounted: show what its hidden value holds
  const init = (root) => {
    root.querySelectorAll?.("[data-multi]:not([data-multi-ready])").forEach((multi) => {
      multi.dataset.multiReady = "1";
      render(parts(multi));
    });
  };
  new MutationObserver((changes) => changes.forEach((c) => c.addedNodes.forEach((n) => n.nodeType === 1 && init(n.parentNode || n))))
    .observe(document.documentElement, { childList: true, subtree: true });
  document.addEventListener("DOMContentLoaded", () => init(document));

  document.addEventListener("click", (event) => {
    const p = parts(event.target);
    if (!p) {
      document.querySelectorAll("[data-multi].is-open").forEach((m) => m.classList.remove("is-open"));
      return;
    }
    if (event.target.closest("[data-multi-toggle]")) {
      event.preventDefault();
      return isOpen(p) ? close(p, false) : open(p);
    }
    if (event.target.closest("[data-multi-panel]")) {
      // the field sits in a <label>: without this, a click on the panel's background would
      // "click" the label's first button (the box) and close the list
      event.preventDefault();
      const option = event.target.closest(".multi-option");
      if (option) {
        tick(p, option);
        setActive(p, option);
        (p.search || p.toggle).focus();
      }
    }
  });

  document.addEventListener("input", (event) => {
    if (!event.target.matches?.("[data-multi-search]")) return;
    filter(parts(event.target));
  });

  document.addEventListener(
    "keydown",
    (event) => {
      if (!event.target.matches?.("[data-multi-search], [data-multi-toggle]")) return;
      const p = parts(event.target);
      if (!isOpen(p)) {
        if (event.key === "ArrowDown") {
          event.preventDefault();
          open(p);
        }
        return; // Enter on the closed box runs the form as usual
      }
      if (event.key === "ArrowDown" || event.key === "ArrowUp") {
        event.preventDefault();
        const shown = rows(p).filter((row) => !row.hidden);
        const at = shown.indexOf(active(p));
        const next = event.key === "ArrowDown" ? Math.min(at + 1, shown.length - 1) : Math.max(at - 1, 0);
        setActive(p, shown[next] || null);
      } else if (event.key === "Enter" || (event.key === " " && event.target.matches("[data-multi-toggle]"))) {
        // the list is open: Enter ticks, it never runs the form
        event.preventDefault();
        event.stopPropagation();
        if (active(p)) tick(p, active(p));
      } else if (event.key === "Escape") {
        // capture phase + stop: Esc closes this list, not the floating view around it (panes.js)
        event.preventDefault();
        event.stopPropagation();
        close(p, true);
      } else if (event.key === "Tab") {
        close(p, false);
      }
    },
    true,
  );

  // an open list is in the wrong place once the page scrolls or resizes: close it
  const closeAll = (event) => {
    if (event?.target?.closest?.("[data-multi-panel]")) return; // scrolling the list itself
    document.querySelectorAll("[data-multi].is-open").forEach((m) => m.classList.remove("is-open"));
  };
  window.addEventListener("scroll", closeAll, true);
  window.addEventListener("resize", closeAll);
})();
